import{_ as d,o as r,c as o,af as n}from"./chunks/framework.B28LkSoM.js";const b=JSON.parse('{"title":"2027事业单位备考·每日执行清单（v3·680全资源版）","description":"按粉笔680河南系统班真实课程表（91讲逐讲日期+1982课时补充资源）重排的备考执行清单。含资源三分法、每天2讲追课节奏、外部补充课精简到3门、32周阶段表和逐日安排。","frontmatter":{"title":"2027事业单位备考·每日执行清单（v3·680全资源版）","published":"2026-10-20T00:00:00.000Z","tags":["事业单位","备考","学习路线","每日计划"],"description":"按粉笔680河南系统班真实课程表（91讲逐讲日期+1982课时补充资源）重排的备考执行清单。含资源三分法、每天2讲追课节奏、外部补充课精简到3门、32周阶段表和逐日安排。","date":"2026-10-20T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/回收站🗑️/2027事业单位备考每日执行清单-v3.md","filePath":"posts/回收站🗑️/2027事业单位备考每日执行清单-v3.md"}'),s={name:"posts/回收站🗑️/2027事业单位备考每日执行清单-v3.md"};function a(g,t,e,h,l,i){return r(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792454400000"},[...t[0]||(t[0]=[n(`<blockquote><p><strong>v3 替代 v2。</strong> v2 是基于&quot;只有 91 节课要追&quot;的假设写的，看到你的完整截图后，这个假设不成立——<strong>你手上的课包是 129 节核心课 + 1982 课时补充课，合计 2111 课时</strong>。不砍就是灾难。</p><p><strong>三处判断我判错了</strong>，都写进第一节，不藏。</p><p>⚠️ <strong>日常执行请看 <a href="./2027事业单位备考作战表-全程版.html">《全程作战表》</a></strong>——那份有 91 讲逐讲排期、23 节导图逐节、冲刺期逐日，照着做就行。<strong>本文件保留作&quot;资源参考&quot;</strong>：哪个模块配什么、哪些课时该砍、权益怎么用，查这里。</p></blockquote><hr><h2 id="一、你现在到底在哪-三处判断修正" tabindex="-1">一、你现在到底在哪（三处判断修正） <a class="header-anchor" href="#一、你现在到底在哪-三处判断修正" aria-label="Permalink to &quot;一、你现在到底在哪（三处判断修正）&quot;">​</a></h2><h3 id="_1-1-你的真实位置" tabindex="-1">1.1 你的真实位置 <a class="header-anchor" href="#_1-1-你的真实位置" aria-label="Permalink to &quot;1.1 你的真实位置&quot;">​</a></h3><p>从系统班首页和课程回放进度读出来的：</p><table tabindex="0"><thead><tr><th>项</th><th>实际</th></tr></thead><tbody><tr><td>完课率</td><td><strong>9%</strong></td></tr><tr><td>听课时长</td><td><strong>8 小时</strong></td></tr><tr><td>已完成</td><td>判断 1–5（全部 100%）</td></tr><tr><td>部分完成</td><td>判断 6（<strong>31%</strong>）、数学运算 3（<strong>34%</strong>）</td></tr><tr><td>折合完成量</td><td>约 <strong>5.6 讲</strong></td></tr><tr><td>上次看到</td><td>理论讲练 · 判断 6</td></tr></tbody></table><h3 id="_1-2-课程放出到哪了" tabindex="-1">1.2 课程放出到哪了 <a class="header-anchor" href="#_1-2-课程放出到哪了" aria-label="Permalink to &quot;1.2 课程放出到哪了&quot;">​</a></h3><p>截至昨天（10/19，资料分析 6 已播）：</p><table tabindex="0"><thead><tr><th>模块</th><th>讲数</th><th>日期</th></tr></thead><tbody><tr><td>判断</td><td>12</td><td>9/7 – 9/19</td></tr><tr><td>言语</td><td>10</td><td>9/20 – 9/30</td></tr><tr><td>数学运算</td><td>4</td><td>10/8 – 10/11</td></tr><tr><td>数字推理</td><td>1</td><td>10/12</td></tr><tr><td>资料分析</td><td>6</td><td>10/13 – 10/19</td></tr><tr><td><strong>合计</strong></td><td><strong>33 讲</strong></td><td>—</td></tr></tbody></table><blockquote><p>注意 10/1–10/7 是国庆，没有课（9/30 言语 10 → 10/8 数学运算 1）。</p></blockquote><p><strong>所以你积压 = 33 − 5.6 ≈ 27 讲。</strong> 我之前估&quot;落后 24–27 讲&quot;，蒙对了。</p><h3 id="_1-3-我判错的三处" tabindex="-1">1.3 我判错的三处 <a class="header-anchor" href="#_1-3-我判错的三处" aria-label="Permalink to &quot;1.3 我判错的三处&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>v2 里我写的</th><th>截图里的真相</th><th>影响</th></tr></thead><tbody><tr><td><strong>①</strong></td><td>&quot;680 主观题突破节数很少，给不了写法&quot;</td><td><strong>有 5 讲，而且是河南专属</strong>：判断改错（12/10）、公文逻辑改错（12/11）、材料作文 1–5（12/12–12/16）</td><td>主观题不是&quot;680 的空白&quot;，是&quot;680 压到最后才讲&quot;。<strong>你要提前自己练</strong>，12 月用这 5 讲做校正</td></tr><tr><td><strong>②</strong></td><td>&quot;数字推理是河南特色，全国课不覆盖，必须补一门&quot;</td><td><strong>680 有专门 1 讲</strong>（10/12 数字推理，廖雅云）</td><td>王同学那门课<strong>不用看了</strong>，省 6 小时</td></tr><tr><td><strong>③</strong></td><td>&quot;680 够不够要自己补 6 门 B站课&quot;</td><td>680 覆盖判断 12 讲、言语 10 讲、数量 5 讲（含数字推理）、资料 8 讲、公基 49 讲，<strong>基本全覆盖</strong></td><td>外部课从 6 门砍到 <strong>3 门</strong>，其余全砍</td></tr></tbody></table><p><strong>这三处修正的共同方向是：我上一版高估了&quot;要补什么&quot;，低估了&quot;你已经买了什么&quot;。</strong> 680 的课包比常规机构课完整得多，真正的问题不是&quot;不够&quot;，而是<strong>太多，得砍</strong>。</p><hr><h2 id="二、680-完整资源地图" tabindex="-1">二、680 完整资源地图 <a class="header-anchor" href="#二、680-完整资源地图" aria-label="Permalink to &quot;二、680 完整资源地图&quot;">​</a></h2><h3 id="_2-1-三个数字先看清" tabindex="-1">2.1 三个数字先看清 <a class="header-anchor" href="#_2-1-三个数字先看清" aria-label="Permalink to &quot;2.1 三个数字先看清&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数字</th><th>含义</th></tr></thead><tbody><tr><td><strong>129</strong></td><td>核心课程节数（试听 6 + 导学 7 + 理论讲练 91 + 导图梳理 23 + 拔高 1 + 套卷 1）</td></tr><tr><td><strong>1982</strong></td><td><strong>补充课程课时数</strong>（名师录播、历年试题精讲、时政畅学班、模考解析、全家桶…）</td></tr><tr><td><strong>2111</strong></td><td>合计。按每天听 8 小时，要听 <strong>264 天</strong></td></tr></tbody></table><p><strong>这就是答案的核心：你的资源不是&quot;不够用&quot;，是&quot;用到死也用不完&quot;。</strong> 所以高效利用的第一步不是&quot;多学&quot;，是<strong>明确不学什么</strong>。</p><h3 id="_2-2-核心课-91-讲的完整结构-这是你的主战场" tabindex="-1">2.2 核心课 91 讲的完整结构（这是你的主战场） <a class="header-anchor" href="#_2-2-核心课-91-讲的完整结构-这是你的主战场" aria-label="Permalink to &quot;2.2 核心课 91 讲的完整结构（这是你的主战场）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>讲数</th><th>时间</th><th>处置</th></tr></thead><tbody><tr><td>判断</td><td>12</td><td>9/7–9/19</td><td><strong>听全</strong></td></tr><tr><td>言语</td><td>10</td><td>9/20–9/30</td><td><strong>听全</strong></td></tr><tr><td>数学运算</td><td>4</td><td>10/8–10/11</td><td><strong>听全</strong></td></tr><tr><td>数字推理</td><td>1</td><td>10/12</td><td><strong>听全</strong>（河南特色，680 已覆盖）</td></tr><tr><td>资料分析</td><td>8</td><td>10/13–10/21</td><td><strong>听全</strong>（性价比最高）</td></tr><tr><td>管理</td><td>2</td><td>10/22–10/23</td><td>只读讲义</td></tr><tr><td>经济</td><td>4</td><td>10/24–10/27</td><td><strong>听全</strong></td></tr><tr><td>科技</td><td>3</td><td>10/28–10/30</td><td>只读讲义</td></tr><tr><td>毛中特</td><td>8</td><td>11/1–11/6</td><td><strong>听全</strong></td></tr><tr><td>公文</td><td>2</td><td>11/7–11/8</td><td><strong>听全</strong></td></tr><tr><td>哲学</td><td>4</td><td>11/9–11/12</td><td><strong>听全</strong></td></tr><tr><td>地理</td><td>2</td><td>11/13–11/14</td><td>只读讲义</td></tr><tr><td>河南省情</td><td>1</td><td>11/15</td><td><strong>听全</strong>（河南必考）</td></tr><tr><td>党史</td><td>2</td><td>11/16–11/17</td><td><strong>听全</strong></td></tr><tr><td>文史</td><td>4</td><td>11/18–11/21</td><td>只读讲义</td></tr><tr><td>宪法</td><td>2</td><td>11/23–11/24</td><td><strong>听全</strong></td></tr><tr><td>行政法</td><td>3</td><td>11/25–11/27</td><td><strong>听全</strong></td></tr><tr><td>刑法</td><td>5</td><td>11/28–12/2</td><td><strong>听全</strong></td></tr><tr><td>民法典总则</td><td>2</td><td>12/3–12/4</td><td><strong>听全</strong></td></tr><tr><td>民法典合同</td><td>2</td><td>12/5–12/6</td><td><strong>听全</strong></td></tr><tr><td>物权</td><td>1</td><td>12/7</td><td><strong>听全</strong></td></tr><tr><td>婚姻继承</td><td>1</td><td>12/8</td><td><strong>听全</strong></td></tr><tr><td>侵权人格</td><td>1</td><td>12/9</td><td><strong>听全</strong></td></tr><tr><td><strong>判断改错</strong></td><td>1</td><td>12/10</td><td><strong>听全（主观题）</strong></td></tr><tr><td><strong>公文逻辑改错</strong></td><td>1</td><td>12/11</td><td><strong>听全（主观题）</strong></td></tr><tr><td><strong>材料作文</strong></td><td>5</td><td>12/12–12/16</td><td><strong>听全（主观题）</strong></td></tr></tbody></table><p><strong>合计：听全 80 讲，只读讲义 11 讲（管理 2 + 科技 3 + 地理 2 + 文史 4）。</strong></p><h3 id="_2-3-后三阶段-明确还没上架" tabindex="-1">2.3 后三阶段：明确还没上架 <a class="header-anchor" href="#_2-3-后三阶段-明确还没上架" aria-label="Permalink to &quot;2.3 后三阶段：明确还没上架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>现状</th></tr></thead><tbody><tr><td>拔高提升</td><td>1/11–1/31</td><td>只有 1 节占位，页面写&quot;<strong>预计最晚 27 年 1 月上旬更新至课包</strong>&quot;</td></tr><tr><td>套卷实战</td><td>2/1–2/28</td><td>同上，也是占位</td></tr><tr><td>考前冲刺</td><td>5/1–5/15</td><td>0 节，未上架</td></tr></tbody></table><p><strong>所以 12/16 之后，除导图梳理 23 节（12/17–1/10），你到 2 月底之前没有新课。</strong> 上一版说的&quot;3/1–4/30 空窗 61 天&quot;要扩大成 <strong>1/11–4/30 近 4 个月基本无课</strong>（拔高、套卷只有占位）。这更说明：<strong>方法必须在 12 月学完。</strong></p><h3 id="_2-4-你确认有的权益-逐项告诉你怎么用" tabindex="-1">2.4 你确认有的权益，逐项告诉你怎么用 <a class="header-anchor" href="#_2-4-你确认有的权益-逐项告诉你怎么用" aria-label="Permalink to &quot;2.4 你确认有的权益，逐项告诉你怎么用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权益</th><th>怎么用</th><th>优先级</th></tr></thead><tbody><tr><td><strong>三重 SVIP 18 个月</strong>（职测/公基/综应）+ 面试 VIP 18 个月</td><td>会员价值在<strong>题库解析 + 精品录播</strong>。你的 18 个月内不用再花钱买任何资料</td><td>★★★★★</td></tr><tr><td><strong>每周模考大赛</strong></td><td><strong>每周日参加，只看百分位不看分数。</strong> 这是你唯一能知道自己和河南考生相对位置的工具</td><td>★★★★★</td></tr><tr><td><strong>AI 批改</strong></td><td><strong>专门用于材料作文。</strong> 你 12/16 之前没有真人老师改作文，这是唯一反馈回路。写完立刻批，按批改重写一遍</td><td>★★★★★</td></tr><tr><td><strong>AI 刷题班（299 兑换券）</strong></td><td>见 2.5，是最容易用错的一项</td><td>★★★★</td></tr><tr><td><strong>时政讲练</strong></td><td>每周时政演练 + 每月串讲，<strong>跟它走，不要自己另找时政</strong></td><td>★★★★</td></tr><tr><td><strong>范文精讲 / 精选范文 30 篇</strong></td><td>作文素材来源，12 月学材料作文时集中看</td><td>★★★</td></tr><tr><td><strong>纸质图书 13 册</strong></td><td>见 2.6，<strong>终极密卷两册留到最后</strong></td><td>★★★★</td></tr><tr><td><strong>专属奖学金</strong></td><td>过笔试 100 元、进面且 ≥80 分 200 元</td><td>—</td></tr></tbody></table><h3 id="_2-5-ai-刷题班-最容易用错的一项" tabindex="-1">2.5 AI 刷题班：最容易用错的一项 <a class="header-anchor" href="#_2-5-ai-刷题班-最容易用错的一项" aria-label="Permalink to &quot;2.5 AI 刷题班：最容易用错的一项&quot;">​</a></h3><p>它有四阶体系（理论速通 → 题型强化 → 模块刷题 → 冲刺实战）、智能推题、AI 错题本、AI 试卷分析、预测分、报考提醒。</p><p><strong>用法只有一条：把它当&quot;诊断仪&quot;，不要当&quot;第二套课&quot;。</strong></p><table tabindex="0"><thead><tr><th>✅ 该用</th><th>❌ 别用</th></tr></thead><tbody><tr><td><strong>AI 错题本</strong>：自动归集错题，省你手工整理</td><td><strong>理论速通微课</strong>：和 680 理论讲练重复，看两套必乱</td></tr><tr><td><strong>AI 试卷分析报告</strong>：看模块正确率、答题时长分布</td><td><strong>智能推题推到的新考点</strong>：它不知道你的计划，会把你带偏</td></tr><tr><td><strong>预测分</strong>：每周看一次趋势即可</td><td><strong>把它当主课表</strong>：你的主课表是这份清单</td></tr><tr><td><strong>报考提醒</strong>：4 月选岗时用</td><td>排行榜攀比</td></tr></tbody></table><p><strong>一条硬规则：AI 刷题班每天只用 30 分钟，全部花在&quot;错题复盘 + 试卷分析&quot;上。</strong> 一旦它开始给你排&quot;今日任务&quot;，就超出边界了。</p><h3 id="_2-6-图书-13-册怎么用" tabindex="-1">2.6 图书 13 册怎么用 <a class="header-anchor" href="#_2-6-图书-13-册怎么用" aria-label="Permalink to &quot;2.6 图书 13 册怎么用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书</th><th>用法</th></tr></thead><tbody><tr><td>全家桶图书礼包（13 册）</td><td>工具书，按需查</td></tr><tr><td><strong>理论速通讲义·河南版</strong></td><td>通勤/碎片时间翻，不进主线</td></tr><tr><td><strong>职测考点一本通</strong></td><td><strong>12 月后当速查表</strong>，别从头读</td></tr><tr><td><strong>常识导图背多分</strong></td><td>记常识用，配合 680 常识讲</td></tr><tr><td><strong>终极密卷·职测·河南版</strong></td><td><strong>留到 5 月</strong>，当全真模考</td></tr><tr><td><strong>终极密卷·公基·河南版</strong></td><td><strong>留到 5 月</strong>，同上</td></tr></tbody></table><h3 id="_2-7-被大多数人忽略的三个内置功能" tabindex="-1">2.7 被大多数人忽略的三个内置功能 <a class="header-anchor" href="#_2-7-被大多数人忽略的三个内置功能" aria-label="Permalink to &quot;2.7 被大多数人忽略的三个内置功能&quot;">​</a></h3><p>这三个藏在「课程服务」里，价值很高：</p><table tabindex="0"><thead><tr><th>功能</th><th>怎么用</th></tr></thead><tbody><tr><td><strong>每讲 课前预习题（约 23 题）</strong></td><td><strong>听前先做</strong>。做错了带着问题听，效率翻倍。这是最便宜的高效手段</td></tr><tr><td><strong>每讲 课后作业（≤15 题）</strong></td><td>听完立刻做，别攒</td></tr><tr><td><strong>AI 课程脉络（课后 12 小时生成）</strong></td><td>自动生成这讲的知识脉络。<strong>用它替代你手写&quot;默写骨架&quot;的一半工作</strong>，你只需补自己的问号</td></tr></tbody></table><h3 id="_2-8-积累专区-碎片时间的正确用法" tabindex="-1">2.8 积累专区：碎片时间的正确用法 <a class="header-anchor" href="#_2-8-积累专区-碎片时间的正确用法" aria-label="Permalink to &quot;2.8 积累专区：碎片时间的正确用法&quot;">​</a></h3><p>里面有：速算训练、资料找数、高频成语、必备实词、削弱加强、类比推理、政治积累/时政。</p><p><strong>用法：只在碎片时间用</strong>（排队、饭后、睡前 15 分钟），每次 10–15 题。<strong>不要占用整块时间</strong>，整块时间给听课和整卷。</p><hr><h2 id="三、92-的资源要主动放弃" tabindex="-1">三、92% 的资源要主动放弃 <a class="header-anchor" href="#三、92-的资源要主动放弃" aria-label="Permalink to &quot;三、92% 的资源要主动放弃&quot;">​</a></h2><p><strong>这是这一版最重要的一节。</strong></p><table tabindex="0"><thead><tr><th>资源</th><th>课时</th><th>处置</th><th>理由</th></tr></thead><tbody><tr><td><strong>680 核心课 91 讲</strong></td><td>~190h</td><td>✅ <strong>听 80 讲 + 只读讲义 11 讲</strong></td><td>主线，你的分数来源</td></tr><tr><td>导图梳理 23 节</td><td>~35h</td><td>✅ <strong>全听</strong>（12/17 起）</td><td>二轮骨架，用来对照你的清单找漏洞</td></tr><tr><td>课时内时政演练</td><td>—</td><td>✅ 每周跟</td><td>时政不能自己找</td></tr><tr><td><strong>名师理论录播课 97 课时</strong></td><td>97h</td><td>❌ <strong>不看</strong></td><td>和 680 理论讲练<strong>同一批内容的录播版</strong>，重复</td></tr><tr><td><strong>粉笔全家桶 1022 课时</strong></td><td>1022h</td><td>❌ <strong>不看</strong></td><td>全科通识课，你的 680 已经是河南专项版，这个是全国版</td></tr><tr><td><strong>全家桶政治理论+常识 611 课时</strong></td><td>611h</td><td>❌ <strong>不看</strong></td><td>同上，且与公基政治重复</td></tr><tr><td><strong>2026 考季时政畅学班 96 课时</strong></td><td>96h</td><td>❌ <strong>不看</strong></td><td>2026 考季的时政，对你 2027 年 5 月考试过期了</td></tr><tr><td>2027 考季时政畅学班 12 课时</td><td>12h</td><td>✅ 看</td><td>这个才是你的考季</td></tr><tr><td>模考大赛解析课 68 + 20 课时</td><td>88h</td><td>⚠️ <strong>只看你做错的那几套</strong></td><td>全看是浪费，挑错题</td></tr><tr><td>历年试题精讲 19 课时</td><td>19h</td><td>✅ 6 月起看（河南真题轮）</td><td>有价值</td></tr><tr><td>精选范文 30 篇</td><td>30h</td><td>⚠️ 12 月看 10 篇即可</td><td>看多了也不会写</td></tr><tr><td>试听课 6 节</td><td>—</td><td>❌ 不看</td><td>已购课，试听无意义</td></tr><tr><td>课前导学 7 节</td><td>—</td><td>⚠️ 只看「考情介绍」1 节</td><td>其余是给零基础扫盲的</td></tr></tbody></table><p><strong>砍掉的总量：约 1800 课时 ≈ 225 个工作日。</strong></p><blockquote><p><strong>一句话原则</strong>：<strong>这个课包里 92% 的内容是&quot;给不同人准备的&quot;，不是&quot;给同一个人准备的&quot;。</strong> 全家桶是给没买专业课的人、录播课是给错过直播的人、2026 时政是给去年考生准备的。<strong>你只需要河南 680 的 91 讲 + 导图 23 节 + 当季时政。</strong></p></blockquote><hr><h2 id="四、外部补充课-从-6-门砍到-3-门" tabindex="-1">四、外部补充课：从 6 门砍到 3 门 <a class="header-anchor" href="#四、外部补充课-从-6-门砍到-3-门" aria-label="Permalink to &quot;四、外部补充课：从 6 门砍到 3 门&quot;">​</a></h2><p>因为 680 覆盖比预想完整，外部课大幅缩减：</p><table tabindex="0"><thead><tr><th>保留</th><th>为什么还是需要</th><th>什么时候看</th></tr></thead><tbody><tr><td><strong>资料速算 · 花生十三</strong></td><td>680 资料分析 8 讲讲得完整，但<strong>速算技巧（截位、化同、差分）通常只带过</strong>，而这决定你的做题速度上限</td><td>10/13 起同步（资料分析模块期间）</td></tr><tr><td><strong>公文改错 · 公考李致</strong></td><td>680 的公文逻辑改错<strong>12/11 才讲</strong>，你需要提前打底</td><td>现在就开始，每周 2 篇</td></tr><tr><td><strong>作文结构 · 醒醒最厉害</strong></td><td>680 的材料作文 1–5 <strong>12/12 才讲</strong>，太晚</td><td>现在就开始，每两周 1 篇</td></tr></tbody></table><p><strong>砍掉的 3 门及理由</strong>：</p><ul><li>❌ 龙飞图推 → 680 判断 12 讲已含图推系统方法，重复</li><li>❌ 花生十三形式逻辑 → 680 判断已含逻辑判断</li><li>❌ 王同学数字推理 / 刘文超数量 / 阿里木江言语 / 马克公基 → 680 全部覆盖</li></ul><blockquote><p><strong>注意这三门保留课的共同点：都是&quot;680 排得太晚&quot;或&quot;680 讲得浅&quot;的地方，不是&quot;680 没有&quot;的地方。</strong> 判断标准要精确。</p></blockquote><hr><h2 id="五、追得完吗-每天-2-讲-12-2-收工" tabindex="-1">五、追得完吗：每天 2 讲，12/2 收工 <a class="header-anchor" href="#五、追得完吗-每天-2-讲-12-2-收工" aria-label="Permalink to &quot;五、追得完吗：每天 2 讲，12/2 收工&quot;">​</a></h2><h3 id="_5-1-测算" tabindex="-1">5.1 测算 <a class="header-anchor" href="#_5-1-测算" aria-label="Permalink to &quot;5.1 测算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>数字</th></tr></thead><tbody><tr><td>要听</td><td><strong>80 讲</strong>（11 讲只读讲义，不算听课）</td></tr><tr><td>已完成</td><td>5.6 讲</td></tr><tr><td><strong>待听</strong></td><td><strong>74.4 讲</strong></td></tr><tr><td>今天到 12/16</td><td><strong>57 天</strong></td></tr><tr><td>1.5 倍速每讲耗时</td><td>约 1.4 小时（2 小时直播 × 1.5 倍速 + 暂停批注）</td></tr><tr><td>每天 2 讲</td><td>2.8 小时 → <strong>43 天完成，12 月 2 日收工</strong></td></tr><tr><td>每天 1.5 讲</td><td>2.1 小时 → 57 天完成，12 月 16 日刚好卡线</td></tr></tbody></table><p><strong>结论：每天 2 讲，12/2 就能把 80 讲全部消化完，比课程 12/16 结束早两周。</strong> 这两周余量给你补 11 讲的讲义、以及赶作文进度。</p><p><strong>积压什么时候追平</strong>：新课每周放 7 讲，你每周消化 12 讲，净追 5 讲/周 → <strong>11 月 24 日左右追平</strong>，之后就是正常跟课。</p><h3 id="_5-2-必须-1-5-倍速" tabindex="-1">5.2 必须 1.5 倍速 <a class="header-anchor" href="#_5-2-必须-1-5-倍速" aria-label="Permalink to &quot;5.2 必须 1.5 倍速&quot;">​</a></h3><table tabindex="0"><thead><tr><th>速度</th><th>每讲耗时</th><th>每天 2 讲</th><th>一天总学习时长</th></tr></thead><tbody><tr><td><strong>1.5 倍速</strong></td><td>1.4h</td><td>2.8h</td><td><strong>7.5h</strong> ✅</td></tr><tr><td>1.25 倍速</td><td>1.7h</td><td>3.4h</td><td>8.1h ⚠️ 偏紧</td></tr><tr><td>1.0 倍速</td><td>2.1h</td><td>4.2h</td><td><strong>8.9h</strong> ❌ 三周必崩</td></tr></tbody></table><p><strong>1.5 倍速下，每天 7.5 小时刚好卡在你说的 6–8 小时上限内。</strong> 原速会直接溢出。</p><h3 id="_5-3-听课的三个具体动作" tabindex="-1">5.3 听课的三个具体动作 <a class="header-anchor" href="#_5-3-听课的三个具体动作" aria-label="Permalink to &quot;5.3 听课的三个具体动作&quot;">​</a></h3><ol><li><strong>听前先做课前预习题（23 题）</strong>——做错的题就是你这次要重点听的地方</li><li><strong>听时只标三种颜色</strong>：黄＝重点、红＝没懂、蓝＝记忆法。不抄</li><li><strong>听完看 AI 课程脉络</strong>，对照自己脑中的骨架，缺的补上——<strong>这一步替代了原来手写默写骨架的一半工作量</strong></li></ol><hr><h2 id="六、每天必打钩的-9-件事" tabindex="-1">六、每天必打钩的 9 件事 <a class="header-anchor" href="#六、每天必打钩的-9-件事" aria-label="Permalink to &quot;六、每天必打钩的 9 件事&quot;">​</a></h2><ul><li>[ ] <strong>自测①（早 20 分钟）</strong>：不看书回忆昨天的清单</li><li>[ ] <strong>课前预习题</strong>：听前做完</li><li>[ ] <strong>680 听课 2 讲</strong>（1.5 倍速，含批注）</li><li>[ ] <strong>课后作业 + 章节题</strong>：听完立刻做</li><li>[ ] <strong>看 AI 课程脉络</strong>，补自己的骨架</li><li>[ ] <strong>专项刷题</strong>：当周模块限时刷（题量见第七节）</li><li>[ ] <strong>错题归因</strong>（+ AI 错题本）</li><li>[ ] <strong>自测②（晚 30 分钟）</strong>：默写今天的清单</li><li>[ ] <strong>时政 20 分钟 + 22:30 前睡</strong></li></ul><p><strong>每周额外</strong>：周六手写作文（每两周 1 篇全文）｜周日上午改错 2 篇｜<strong>周日参加模考大赛</strong>｜周日下午完全休息｜周日 20:00 复盘 30 分钟。</p><hr><h2 id="七、每日时间骨架" tabindex="-1">七、每日时间骨架 <a class="header-anchor" href="#七、每日时间骨架" aria-label="Permalink to &quot;七、每日时间骨架&quot;">​</a></h2><h3 id="理论讲练期-w1–w9-10-20-–-12-20-约-7-5-小时" tabindex="-1">理论讲练期（W1–W9，10/20 – 12/20，约 7.5 小时） <a class="header-anchor" href="#理论讲练期-w1–w9-10-20-–-12-20-约-7-5-小时" aria-label="Permalink to &quot;理论讲练期（W1–W9，10/20 – 12/20，约 7.5 小时）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>07:30–07:50  自测①  不看书回忆昨天的清单              20 分钟</span></span>
<span class="line"><span>08:00–08:20  课前预习题（今天第一讲的）                  20 分钟</span></span>
<span class="line"><span>08:20–11:00  680 听课 2 讲（1.5 倍速）+ 讲义三色批注      2.8 小时</span></span>
<span class="line"><span>11:00–11:50  看 AI 课程脉络 + 课后作业 + 章节题           0.8 小时</span></span>
<span class="line"><span>11:50–14:00  午饭 + 午休（必须睡 20–30 分钟）</span></span>
<span class="line"><span>14:00–15:00  当周模块限时刷题                           1 小时</span></span>
<span class="line"><span>15:00–16:40  继续刷题 + 对答案                           1.7 小时</span></span>
<span class="line"><span>16:40–19:00  晚饭 + 离开书桌</span></span>
<span class="line"><span>19:00–20:00  错题归因 + AI 错题本 + 压自测清单            1 小时</span></span>
<span class="line"><span>20:00–20:20  时政                                      20 分钟</span></span>
<span class="line"><span>20:30–21:00  自测② 默写今天的清单                        30 分钟</span></span>
<span class="line"><span>21:00–21:15  自测③ 只过红笔标记                           15 分钟</span></span>
<span class="line"><span>22:30 前     睡觉</span></span></code></pre></div><p><strong>听课封顶 2.8 小时。</strong> 超了就是在用&quot;听课&quot;逃避&quot;做题&quot;。</p><blockquote><p><strong>晚上有直播怎么办</strong>：如果当晚直播的正好是你在学的模块，可以跟；跟不上第二天回放补。<strong>但不要为了跟直播打乱上午 2 讲的节奏</strong>——你是追课状态，回放比直播更可控（能跳、能倍速）。</p></blockquote><h3 id="导图梳理期-w10–w12-12-21-–-1-10-约-6-5-小时" tabindex="-1">导图梳理期（W10–W12，12/21 – 1/10，约 6.5 小时） <a class="header-anchor" href="#导图梳理期-w10–w12-12-21-–-1-10-约-6-5-小时" aria-label="Permalink to &quot;导图梳理期（W10–W12，12/21 – 1/10，约 6.5 小时）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>07:30–07:50  自测①</span></span>
<span class="line"><span>08:00–11:00  导图梳理 1 节 + 用它对照自己清单标漏洞        2.5 小时</span></span>
<span class="line"><span>11:00–11:50  漏洞章节回炉</span></span>
<span class="line"><span>14:00–16:40  职测整卷 / 公基二轮</span></span>
<span class="line"><span>19:00–20:00  错题归因 + 清单更新</span></span>
<span class="line"><span>20:30–21:00  自测②③</span></span></code></pre></div><p><strong>这一段的核心动作只有一件：拿 680 的导图和你的自测清单做差集，差的就是漏洞。</strong></p><h3 id="无课期-w13–w28-1-11-–-4-30-约-7-小时" tabindex="-1">无课期（W13–W28，1/11 – 4/30，约 7 小时） <a class="header-anchor" href="#无课期-w13–w28-1-11-–-4-30-约-7-小时" aria-label="Permalink to &quot;无课期（W13–W28，1/11 – 4/30，约 7 小时）&quot;">​</a></h3><p>拔高和套卷只有 1 节占位（&quot;最晚 27 年 1 月上旬更新&quot;），所以这近 4 个月<strong>基本靠自己</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>08:00–09:30  职测整卷（严格 90 分钟）</span></span>
<span class="line"><span>09:45–11:15  公基整卷（手写）</span></span>
<span class="line"><span>14:00–16:30  整卷精析（逐题写原因）</span></span>
<span class="line"><span>19:00–20:30  时政 + 作文素材</span></span>
<span class="line"><span>20:30–21:00  自测②</span></span></code></pre></div><p><strong>上午连做两套卷、下午全用来精析。</strong> 这是唯一正确的结构。</p><hr><h2 id="八、笔记流程-讲义-→-三色-→-ai脉络-→-清单" tabindex="-1">八、笔记流程：讲义 → 三色 → AI脉络 → 清单 <a class="header-anchor" href="#八、笔记流程-讲义-→-三色-→-ai脉络-→-清单" aria-label="Permalink to &quot;八、笔记流程：讲义 → 三色 → AI脉络 → 清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步</th><th>时间</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td>听前</td><td>做课前预习题，标出错题</td></tr><tr><td>2</td><td>听课中</td><td>讲义只标三种色：黄重点、红没懂、蓝记忆法。<strong>不抄</strong></td></tr><tr><td>3</td><td>听完</td><td><strong>看 AI 课程脉络</strong>，对照脑中骨架，缺的补在讲义空白处</td></tr><tr><td>4</td><td>当天或次日</td><td>把这一讲<strong>压缩成自测清单</strong></td></tr><tr><td>5</td><td>周日</td><td>本周清单合成一张 A4 打印，下周每天早上做自测①</td></tr></tbody></table><p><strong>第 3 步是 v3 新增的</strong>：AI 课程脉络已经替你做完了&quot;骨架提取&quot;，你只补&quot;自己的问号&quot;。这能省下原来手写默写的 60% 时间。</p><h3 id="载体分工-别搞错" tabindex="-1">载体分工（别搞错） <a class="header-anchor" href="#载体分工-别搞错" aria-label="Permalink to &quot;载体分工（别搞错）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>内容</th><th>载体</th><th>理由</th></tr></thead><tbody><tr><td>讲义批注、自测清单</td><td>平板</td><td>省时间、可检索</td></tr><tr><td><strong>大作文</strong></td><td><strong>纸质手写，限时</strong></td><td>考场手写 800–1000 字</td></tr><tr><td><strong>公文改错</strong></td><td><strong>纸质</strong>，写在打印题上</td><td>练&quot;扫一眼发现格式位置&quot;</td></tr><tr><td>真题整卷、终极密卷</td><td>纸质</td><td>还原考场</td></tr></tbody></table><h3 id="自测清单长什么样" tabindex="-1">自测清单长什么样 <a class="header-anchor" href="#自测清单长什么样" aria-label="Permalink to &quot;自测清单长什么样&quot;">​</a></h3><p>一个模块一页，只写&quot;能出题的东西&quot;，200 字以内。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>图形推理（一页示例）</span></span>
<span class="line"><span>  属性规律：对称性（轴/中心）/ 曲直 / 开闭   ← 先看这个，最快</span></span>
<span class="line"><span>  位置规律：平移（步长）/ 旋转（角度顺逆）/ 翻转（对称）</span></span>
<span class="line"><span>  样式规律：加减同异 / 黑白运算 / 遍历</span></span>
<span class="line"><span>  数量规律：点 / 线（笔画数）/ 面 / 角 / 素</span></span>
<span class="line"><span>  ★ 顺序：属性 → 位置 → 样式 → 数量，别一上来就数</span></span></code></pre></div><p>写进清单的四种：<strong>数字并列项</strong>、<strong>易混对比</strong>、<strong>原话挖空</strong>、<strong>你的问号</strong>。</p><h3 id="为什么还要每天两次自测" tabindex="-1">为什么还要每天两次自测 <a class="header-anchor" href="#为什么还要每天两次自测" aria-label="Permalink to &quot;为什么还要每天两次自测&quot;">​</a></h3><p>Dunlosky 等汇总 61 年研究的评级里，<strong>练习测试</strong>和<strong>分散练习</strong>是高效用，<strong>反复阅读、划线、摘抄</strong>是低效用——&quot;批注讲义&quot;正好属于后者。</p><p>所以批注之后必须插两次<strong>主动回忆</strong>。<strong>批注是输入，自测才是记忆。</strong></p><hr><h2 id="九、每周固定动作" tabindex="-1">九、每周固定动作 <a class="header-anchor" href="#九、每周固定动作" aria-label="Permalink to &quot;九、每周固定动作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>动作</th></tr></thead><tbody><tr><td><strong>周六 19:00–20:00</strong></td><td>手写大作文（<strong>每两周 1 篇全文，中间那周只写提纲</strong>）</td></tr><tr><td><strong>周日上午</strong></td><td>公文改错 2 篇（三种形式轮换）</td></tr><tr><td><strong>周日下午</strong></td><td><strong>参加模考大赛</strong>（若在周日）；之后完全休息</td></tr><tr><td><strong>周日 20:00–20:30</strong></td><td>复盘 30 分钟 + 下周计划</td></tr><tr><td><strong>每月最后一个周日</strong></td><td>全真模拟：上午职测 90 分钟，下午公基 90 分钟</td></tr></tbody></table><h3 id="周日复盘-只问五句" tabindex="-1">周日复盘，只问五句 <a class="header-anchor" href="#周日复盘-只问五句" aria-label="Permalink to &quot;周日复盘，只问五句&quot;">​</a></h3><ol><li>这周听了_____讲？（目标 12）</li><li>这周做了_____题？（目标 350）</li><li>积压还差_____讲？（目标每周减 5）</li><li>这周哪块最卡？（只写一个）</li><li>下周要改的一件事？（只写一件）</li></ol><hr><h2 id="十、32-周总表" tabindex="-1">十、32 周总表 <a class="header-anchor" href="#十、32-周总表" aria-label="Permalink to &quot;十、32 周总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>周次</th><th>日期</th><th>680 对应</th><th>目标</th><th>日投入</th></tr></thead><tbody><tr><td><strong>理论讲练期</strong></td><td>W1–W9</td><td>10/20 – 12/20</td><td>91 讲（12/16 结束）</td><td><strong>每天 2 讲，12/2 听完 80 讲</strong>；11/24 追平积压；作文 ≥6 篇</td><td>7.5h</td></tr><tr><td><strong>导图收尾期</strong></td><td>W10–W12</td><td>12/21 – 1/10</td><td>导图梳理 23 节</td><td>导图与清单做差集，补漏洞；公基一轮完</td><td>6.5h</td></tr><tr><td><strong>无课攻坚期</strong></td><td>W13–W28</td><td>1/11 – 4/30</td><td>仅 1 节占位</td><td>河南真题 2 遍；专项攻坚；整卷稳定 65；4 月报名选岗</td><td>7h</td></tr><tr><td><strong>考前冲刺</strong></td><td>W29–W31</td><td>5/1 – 5/23</td><td>考前冲刺 5/1–5/15</td><td>时政 3 遍；作文押题；<strong>不做新题</strong></td><td>7h</td></tr><tr><td><strong>笔试周</strong></td><td>W32</td><td>5/24 – 5/30</td><td>—</td><td>笔试；考完当天练结构化面试</td><td>—</td></tr></tbody></table><p><strong>累计</strong>：作文 30 篇、改错 60 篇、刷题 1.5 万题以上、整卷稳定 65 分。</p><blockquote><p><strong>最该警惕的是 W13–W28 这 16 周（1/11–4/30）。</strong> 680 只有占位课，没有节奏推着你。<strong>这四个月是分差拉开的阶段，也是崩盘最多的阶段。</strong> 对策：每周写死 2 套整卷，周日复盘只核这一件事。</p></blockquote><hr><h2 id="十一、逐日表-w1–w4-每天-2-讲" tabindex="-1">十一、逐日表（W1–W4，每天 2 讲） <a class="header-anchor" href="#十一、逐日表-w1–w4-每天-2-讲" aria-label="Permalink to &quot;十一、逐日表（W1–W4，每天 2 讲）&quot;">​</a></h2><blockquote><p>按你实际进度接续：从<strong>判断 6</strong> 开始。新课直播晚上可跟，跟不上次日回放。</p></blockquote><h3 id="w1-10-20-周二-–-10-25-周日-判断收尾-言语起步" tabindex="-1">W1（10/20 周二 – 10/25 周日）｜判断收尾 + 言语起步 <a class="header-anchor" href="#w1-10-20-周二-–-10-25-周日-判断收尾-言语起步" aria-label="Permalink to &quot;W1（10/20 周二 – 10/25 周日）｜判断收尾 + 言语起步&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>680 听课（2 讲/天）</th><th>下午刷题</th><th>晚上</th></tr></thead><tbody><tr><td><strong>二 10/20</strong></td><td>判断 6（已看 31%，补完）+ 判断 7</td><td>图推 20 + 定义 15</td><td>清单：图推一页</td></tr><tr><td><strong>三 10/21</strong></td><td>判断 8 + 判断 9</td><td>类比 15 + 逻辑 20</td><td>清单：类比五大关系</td></tr><tr><td><strong>四 10/22</strong></td><td>判断 10 + 判断 11</td><td>逻辑 20 + 图推 20</td><td>清单：逻辑判断</td></tr><tr><td><strong>五 10/23</strong></td><td>判断 12 + 言语 1</td><td>言语 30</td><td>清单：判断合一张</td></tr><tr><td><strong>六 10/24</strong></td><td>言语 2 + 言语 3</td><td>言语 30</td><td><strong>19:00 手写作文提纲</strong>（醒醒前两节）</td></tr><tr><td><strong>日 10/25</strong></td><td>言语 4 + 言语 5</td><td>言语 30</td><td><strong>模考大赛</strong> + 复盘 30 分钟</td></tr></tbody></table><p><strong>W1 目标</strong>：12 讲 ｜ 判断模块清单 4 张 ｜ 判断全模块收尾</p><hr><h3 id="w2-10-26-–-11-1-言语收尾-数量" tabindex="-1">W2（10/26 – 11/1）｜言语收尾 + 数量 <a class="header-anchor" href="#w2-10-26-–-11-1-言语收尾-数量" aria-label="Permalink to &quot;W2（10/26 – 11/1）｜言语收尾 + 数量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>680 听课</th><th>下午刷题</th><th>晚上</th></tr></thead><tbody><tr><td><strong>一 10/26</strong></td><td>言语 6 + 言语 7</td><td>逻辑填空 30</td><td>清单：逻辑填空</td></tr><tr><td><strong>二 10/27</strong></td><td>言语 8 + 言语 9</td><td>片段阅读 20</td><td>清单：片段阅读</td></tr><tr><td><strong>三 10/28</strong></td><td>言语 10 + 数学运算 1</td><td>言语 30</td><td>清单：言语合一张</td></tr><tr><td><strong>四 10/29</strong></td><td>数学运算 2 + 数学运算 3（已看 34%，补完）</td><td>数量 10</td><td>清单：数量公式</td></tr><tr><td><strong>五 10/30</strong></td><td>数学运算 4 + 数字推理</td><td>数量 10 + 数推 10</td><td><strong>定数量放弃清单</strong></td></tr><tr><td><strong>六 10/31</strong></td><td>资料分析 1 + 资料分析 2</td><td>材料 2 篇</td><td><strong>19:00 手写作文全文 1</strong></td></tr><tr><td><strong>日 11/1</strong></td><td>资料分析 3 + 资料分析 4</td><td>材料 2 篇</td><td><strong>模考 + 改错 2 篇</strong> + 复盘</td></tr></tbody></table><p><strong>W2 目标</strong>：12 讲 ｜ 职测除资料外全部过完 ｜ <strong>写出数量放弃清单</strong> ｜ 作文 1 篇全文</p><hr><h3 id="w3-11-2-–-11-8-资料分析-性价比最高" tabindex="-1">W3（11/2 – 11/8）｜资料分析（性价比最高） <a class="header-anchor" href="#w3-11-2-–-11-8-资料分析-性价比最高" aria-label="Permalink to &quot;W3（11/2 – 11/8）｜资料分析（性价比最高）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>680 听课</th><th>下午刷题</th><th>晚上</th></tr></thead><tbody><tr><td><strong>一 11/2</strong></td><td>资料分析 5 + 6（补 10/18–19）</td><td>材料 2 篇 + <strong>花生十三速算 1–2 集</strong></td><td>清单：术语+公式</td></tr><tr><td><strong>二 11/3</strong></td><td>资料分析 7（10/20 直播回放）</td><td>材料 2 篇 + 速算 3 集</td><td>清单：增长公式</td></tr><tr><td><strong>三 11/4</strong></td><td>资料分析 8（10/21）</td><td>材料 2 篇 + 速算 4 集</td><td>清单：比重三公式</td></tr><tr><td><strong>四 11/5</strong></td><td>管理 1（<strong>只读讲义 40 分钟</strong>）+ 管理 2（同）</td><td>材料 2 篇 + 速算 5 集</td><td>清单：资料合一张</td></tr><tr><td><strong>五 11/6</strong></td><td>经济 1 + 经济 2</td><td><strong>教资 10:00 出分 → 定 12/5 面试</strong>；材料 2 篇</td><td>清单：经济术语</td></tr><tr><td><strong>六 11/7</strong></td><td>经济 3 + 经济 4</td><td>材料 2 篇（限时 12 分钟/篇）</td><td><strong>19:00 手写作文提纲</strong></td></tr><tr><td><strong>日 11/8</strong></td><td>科技 1–3（<strong>只读讲义</strong>，2 小时）</td><td>改错 2 篇</td><td><strong>模考 + 复盘</strong>（对一遍：听课数 / 积压数 / 题量）</td></tr></tbody></table><p><strong>W3 目标</strong>：资料分析单篇 12 分钟内 ｜ 管理+科技 11 讲里的 5 讲用讲义解决 ｜ 作文 3 篇累计</p><hr><h3 id="w4-11-9-–-11-15-公基政治开局" tabindex="-1">W4（11/9 – 11/15）｜公基政治开局 <a class="header-anchor" href="#w4-11-9-–-11-15-公基政治开局" aria-label="Permalink to &quot;W4（11/9 – 11/15）｜公基政治开局&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>680 听课</th><th>下午刷题</th><th>晚上</th></tr></thead><tbody><tr><td><strong>一 11/9</strong></td><td>哲学 1 + 哲学 2</td><td>公基政治 30</td><td><strong>清单：马原一页</strong></td></tr><tr><td><strong>二 11/10</strong></td><td>哲学 3 + 哲学 4</td><td>马原 30</td><td>清单补辩证法</td></tr><tr><td><strong>三 11/11</strong></td><td>毛中特 1 + 毛中特 2</td><td>毛中特 30</td><td>清单补认识论/唯物史观</td></tr><tr><td><strong>四 11/12</strong></td><td>毛中特 3 + 毛中特 4</td><td>毛中特 30</td><td>清单：毛中特时间线</td></tr><tr><td><strong>五 11/13</strong></td><td>毛中特 5 + 毛中特 6</td><td>公基政治 30</td><td>清单补中特理论</td></tr><tr><td><strong>六 11/14</strong></td><td>毛中特 7 + 毛中特 8</td><td>公基政治 30</td><td><strong>19:00 手写作文全文 2</strong></td></tr><tr><td><strong>日 11/15</strong></td><td>公文 1 + 公文 2</td><td>改错 2 篇（公文格式）</td><td><strong>模考 + 检查点一</strong></td></tr></tbody></table><p><strong>W4 目标</strong>：12 讲 ｜ 政治板块清单完成 ｜ 作文 2 篇全文 ｜ <strong>过检查点一</strong></p><hr><h2 id="十二、w5-之后任务包" tabindex="-1">十二、W5 之后任务包 <a class="header-anchor" href="#十二、w5-之后任务包" aria-label="Permalink to &quot;十二、W5 之后任务包&quot;">​</a></h2><h3 id="w5–w9-11-16-–-12-20-按课程表跟完-91-讲" tabindex="-1">W5–W9（11/16 – 12/20）｜按课程表跟完 91 讲 <a class="header-anchor" href="#w5–w9-11-16-–-12-20-按课程表跟完-91-讲" aria-label="Permalink to &quot;W5–W9（11/16 – 12/20）｜按课程表跟完 91 讲&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>日期</th><th>680 内容</th><th>重点</th></tr></thead><tbody><tr><td>W5</td><td>11/16–11/22</td><td>地理 2（讲义）+ 河南省情 1 + 党史 2 + 文史 4（讲义）</td><td><strong>11/24 前追平积压</strong></td></tr><tr><td>W6</td><td>11/23–11/29</td><td>宪法 2 + 行政法 3 + 刑法 1–2</td><td>法律开局，拉对比表</td></tr><tr><td>W7</td><td>11/30–12/6</td><td>刑法 3–5 + 民法典总则 2 + 合同 1–2</td><td>法律最大板块，慢一点</td></tr><tr><td>W8</td><td>12/7–12/13</td><td>物权 1 + 婚姻继承 1 + 侵权 1 + <strong>判断改错 1 + 公文逻辑改错 1</strong></td><td>现在才知道&quot;判断改错&quot;考什么</td></tr><tr><td>W9</td><td>12/14–12/20</td><td><strong>材料作文 1–5</strong></td><td><strong>作文方法校正：用 680 的方法重写你 W2 那篇</strong></td></tr></tbody></table><blockquote><p><strong>W9 那个动作很关键</strong>：12/12–12/16 680 讲完材料作文 5 讲后，<strong>把你 W2 写的第一篇作文用新方法重写一遍</strong>。同一道题前后对比，你能直接看到方法差在哪——这比再写 5 篇新题有用。</p></blockquote><h3 id="w10–w12-12-21-–-1-10-导图梳理" tabindex="-1">W10–W12（12/21 – 1/10）｜导图梳理 <a class="header-anchor" href="#w10–w12-12-21-–-1-10-导图梳理" aria-label="Permalink to &quot;W10–W12（12/21 – 1/10）｜导图梳理&quot;">​</a></h3><p>23 节按模块分布：言语 2、判断 2、数量 1、资料 1、公文逻辑改错 1、材料作文 1、法理宪法 1、行政法 1、刑法 1、民法 2、党史 1、毛中特 2、科技 1、文史 1、经济 1、公文 1、管理 1、哲学 1、地理 1。</p><p><strong>每天 1 节 + 做一件事：把这一模块的导图和你的自测清单并排，标出&quot;导图有、清单没有&quot;的部分。</strong> 那就是漏洞。</p><h3 id="w13–w28-1-11-–-4-30-无课期-16-周" tabindex="-1">W13–W28（1/11 – 4/30）｜无课期，16 周 <a class="header-anchor" href="#w13–w28-1-11-–-4-30-无课期-16-周" aria-label="Permalink to &quot;W13–W28（1/11 – 4/30）｜无课期，16 周&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>日期</th><th>主任务</th></tr></thead><tbody><tr><td>W13–W16</td><td>1/11–2/7</td><td>河南真题第一轮（2023、2024 卷）｜每周 2 套整卷｜含除夕 2/6 降强度别断档</td></tr><tr><td>W17–W19</td><td>2/8–2/28</td><td>河南真题（2025 卷）+ 专项攻坚｜第 1 次人工精批（129 元/次）</td></tr><tr><td>W20–W23</td><td>3/1–3/28</td><td>真题第二轮（只做错题）｜只攻最弱两模块｜第 2 次精批</td></tr><tr><td>W24–W25</td><td>3/29–4/11</td><td>时政第 1 遍 + 作文押题 6 主题｜整卷按 65 分考核</td></tr><tr><td>W26</td><td>4/12–4/18</td><td><strong>公告预计发布</strong>：下载《考试大纲》逐条对，确认主观题字数题型</td></tr><tr><td>W27</td><td>4/19–4/25</td><td><strong>报名 + 选岗</strong>｜盯核减｜打岗位备注栏电话确认专业</td></tr><tr><td>W28</td><td>4/26–4/30</td><td>选岗收尾 + 弱项补漏 ｜<strong>检查点四</strong></td></tr></tbody></table><h3 id="w29–w32-5-1-–-5-30-冲刺" tabindex="-1">W29–W32（5/1 – 5/30）｜冲刺 <a class="header-anchor" href="#w29–w32-5-1-–-5-30-冲刺" aria-label="Permalink to &quot;W29–W32（5/1 – 5/30）｜冲刺&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周次</th><th>日期</th><th>任务</th></tr></thead><tbody><tr><td>W29</td><td>5/1–5/9</td><td>考前冲刺课（5/1–5/15）+ 改错三形式各 5 篇 + <strong>终极密卷两册开做</strong></td></tr><tr><td>W30</td><td>5/10–5/16</td><td>时政第 3 遍 + 作文押题</td></tr><tr><td>W31</td><td>5/17–5/23</td><td><strong>不做新题</strong>：只看错题本、清单、素材库</td></tr><tr><td>W32</td><td>5/24–5/30</td><td>笔试周。考完当天开始练结构化面试（有 18 个月面试 VIP 可用）</td></tr></tbody></table><hr><h2 id="十三、检查点" tabindex="-1">十三、检查点 <a class="header-anchor" href="#十三、检查点" aria-label="Permalink to &quot;十三、检查点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查点</th><th>时间</th><th>标准</th><th>不达标怎么办</th></tr></thead><tbody><tr><td><strong>一</strong></td><td>W4（11/15）</td><td>听课 ≥48 讲、判断+言语+数量清单成型、作文 2 篇全文、数量放弃清单已定</td><td>W5 减刷题，补听课</td></tr><tr><td><strong>二</strong></td><td><strong>W9（12/20）</strong></td><td><strong>80 讲全部听完</strong>、11 讲讲义解决完、公基一轮完、作文 6 篇、改错 14 篇</td><td>12/21 起导图期节拍轻，用余量补</td></tr><tr><td><strong>三</strong></td><td><strong>W19（2/28）</strong></td><td>方法论全部到位、整卷 ≥60、错题本成型（用 AI 错题本）、作文 15 篇</td><td>3 月无课期必须先补方法，否则失速</td></tr><tr><td><strong>四</strong></td><td><strong>W28（4/30）</strong></td><td>河南真题一遍完、整卷稳定 65、报名选岗已定、作文 24 篇</td><td>5 月只保言语+判断+资料，<strong>放弃数量</strong></td></tr></tbody></table><p><strong>唯一调整原则</strong>：先砍听课，绝不砍作文和改错。</p><hr><h2 id="十四、今晚就能做的-4-件事" tabindex="-1">十四、今晚就能做的 4 件事 <a class="header-anchor" href="#十四、今晚就能做的-4-件事" aria-label="Permalink to &quot;十四、今晚就能做的 4 件事&quot;">​</a></h2><p>已经确认的都确认了，剩下的全是动作：</p><ol><li><strong>打开 AI 刷题班，把&quot;今日任务&quot;关掉</strong>——只留错题本和试卷分析。这是最容易把计划带偏的地方。</li><li><strong>今晚听判断 6 的后 69%</strong>（已看 31%），顺手做完它的课后作业。你判断 1 的作业已完成，说明这个动作你做得到。</li><li><strong>明天上午开始执行 2 讲/天</strong>。判断 7、8 是杨九讲的，接在胡晓晨后面，风格会有变化，正常。</li><li><strong>建对照表</strong>（1.5 小时，只做一次）：把上面 2.2 那张 26 行的模块表抄成一张纸，标上&quot;听全 / 只读讲义&quot;两色。<strong>这张纸就是你这 8 周的导航。</strong></li></ol><hr><h2 id="十五、硬约束与决策点" tabindex="-1">十五、硬约束与决策点 <a class="header-anchor" href="#十五、硬约束与决策点" aria-label="Permalink to &quot;十五、硬约束与决策点&quot;">​</a></h2><h3 id="毕设必须前压" tabindex="-1">毕设必须前压 <a class="header-anchor" href="#毕设必须前压" aria-label="Permalink to &quot;毕设必须前压&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>毕设任务</th></tr></thead><tbody><tr><td>10–12 月</td><td>系统主体功能开发完</td></tr><tr><td>1 月</td><td>收尾 + 测试</td></tr><tr><td>2–3 月</td><td>论文成稿</td></tr><tr><td>4 月</td><td>定稿送审</td></tr><tr><td><strong>5 月</strong></td><td><strong>彻底留空，只给笔试</strong></td></tr></tbody></table><h3 id="两个决策点" tabindex="-1">两个决策点 <a class="header-anchor" href="#两个决策点" aria-label="Permalink to &quot;两个决策点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>事</th><th>怎么定</th></tr></thead><tbody><tr><td><strong>11/6 10:00</strong></td><td>教资出分，面试 12/5–6</td><td>过了花两周碎片时间考；没过就彻底放下</td></tr><tr><td><strong>12/20（检查点二）</strong></td><td>要不要报河南省考（1 月初公告）</td><td>公基职测稳在 60+ → 报；没稳住 → 专心主线</td></tr></tbody></table><h3 id="一条实话" tabindex="-1">一条实话 <a class="header-anchor" href="#一条实话" aria-label="Permalink to &quot;一条实话&quot;">​</a></h3><p>你有 18 个月 SVIP、2111 课时课包、13 册纸质书、AI 批改、每周模考。<strong>工具层面你什么都不缺了，缺的只是&quot;每天 2 讲&quot;这个动作连续做 43 天。</strong></p><p>资源过剩的人最容易死在&quot;再找找还有没有更好的资料&quot;上。</p><hr><blockquote><p><strong>如果只记三件事</strong>：</p><ol><li><strong>92% 的资源要主动放弃</strong>——全家桶 1022 课时、录播课 97 课时、2026 时政 96 课时，全部不看。</li><li><strong>每天 2 讲，12/2 收工</strong>——1.5 倍速，7.5 小时/天，这是唯一能追完又不崩的节奏。</li><li><strong>作文和改错不能等 12 月</strong>——680 排到 12/10–12/16，你现在就得练，12 月用它的方法重写一遍。</li></ol></blockquote>`,153)])])}const u=d(s,[["render",a]]);export{b as __pageData,u as default};
